import { IHikingDuty, IHikingScheduleItem } from '../@types/hiking.baseTypes';
import { IHiker, IHikingData } from '../@types/hiking.types';
import { IHikingMenuExtendedProduct, IHikingMenuFood } from '../@types/hikingMenu.types';
import { IHikingTransfer } from '../@types/hikingTransfers.types';
import { getHikingMenuWeightSummary } from '../menu/components/HikingMenu/components/SummaryPanel/hikingMenuSummary.helper';

export const getHikingStartToFinishDates = (hikingData: IHikingData) => {
  const arr: Date[] = [];
  let cur = hikingData.start;
  while (cur <= hikingData.finish) {
    arr.push(cur);
    cur = new Date(cur.getTime() + 86400000);
  }

  return arr;
};

export interface IDayData {
  date: Date;
  schedules: IHikingScheduleItem[];
  duty: IHikingDuty[];
  transfers: IHikingTransfer[];
  userLoad: { hiker: IHiker; kg: number; pct: number }[];
}

export const getHikingDaysData = ({
  hikingSchedule,
  hikingDuty,
  hikingTransfers,
  hikingFood,
  products,
  hikingData,
}: {
  hikingSchedule: IHikingScheduleItem[];
  hikingDuty: IHikingDuty[];
  hikingTransfers: IHikingTransfer[];
  hikingFood: IHikingMenuFood[];
  products: IHikingMenuExtendedProduct[];
  hikingData: IHikingData;
}) => {
  const minDate = new Date(Math.min(...hikingSchedule.map((hs) => hs.start.getTime())));
  const maxDate = new Date(Math.max(...hikingSchedule.map((hs) => hs.finish.getTime())));

  const byDayMap: Record<string, IDayData> = {};
  let curDate = new Date(minDate.setHours(0, 0, 0, 0)).getTime();

  while (curDate < new Date(maxDate.setHours(23, 59, 59, 999)).getTime()) {
    const d = new Date(curDate);
    const k = d.toLocaleDateString();
    const schedules = hikingSchedule.filter((hs) => {
      const endDay = new Date(curDate + 86400000);
      const isStartToday = hs.start.toLocaleDateString() === d.toLocaleDateString();
      const isFinishToday = hs.finish.toLocaleDateString() === d.toLocaleDateString();
      const isStartBefore = hs.start.getTime() <= d.getTime();
      const isFinishBefore = hs.finish.getTime() >= endDay.getTime();

      return isStartToday || isFinishToday || (isStartBefore && isFinishBefore);
    });

    byDayMap[k] = {
      date: d,
      schedules,
      duty: hikingDuty?.filter((hd) => hd.date.toLocaleDateString() === k) ?? [],
      transfers: hikingTransfers.filter((y) => schedules.some((s) => s.id === y.schedule?.id)),
      userLoad: hikingData.hikers.map((h) => ({ hiker: h, kg: 0, pct: 0 })),
    };

    curDate += 86400000;
  }

  const { dateUserWeightAggregation, maxUserLoads } = getHikingMenuWeightSummary(
    hikingFood,
    products,
    hikingData?.hikers.length ?? 1,
  );

  const dayUserLoads: Record<string, Record<number, number>> = {};

  let startLoads = { ...maxUserLoads };

  Object.entries(dateUserWeightAggregation)
    .sort(([s1], [s2]) => new Date(s1).getTime() - new Date(s2).getTime())
    .forEach(([dateStr, userWeights]) => {
      const dayStr = new Date(dateStr).toISOString().substring(0, 10);
      Object.entries(userWeights).forEach(([u, w]) => {
        const userId = +u;
        startLoads = { ...startLoads, [userId]: startLoads[userId] - w * hikingData.hikers.length };
      });
      dayUserLoads[dayStr] = { ...startLoads };
    });

  const all = Object.values(byDayMap);
  let started = false;
  all.forEach((x) => {
    const dayLo = dayUserLoads?.[x.date.toISOString().substring(0, 10)];
    x.userLoad = hikingData.hikers.map((h) => {
      if (!started && dayLo?.[h.idUser]) started = true;

      const fallback = started ? 0 : maxUserLoads[h.idUser] / 1000;

      const kg = dayLo?.[h.idUser] ? dayLo[h.idUser] / 1000 : fallback;

      return {
        hiker: h,
        kg,
        pct: kg ? (kg / maxUserLoads[h.idUser]) * 100000 : 0,
      };
    });
  });

  return all;
};
